// visca cliento con sesion iniciada
import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../components/cliente.css";
// header y footer
import Footer from '../components/Footer.jsx'; 

const Cliente = () => {
    return (
        <>
        
        <main>
            <Link to="/cliente" className="boton-catalogo">cliente</Link>
            <Link to="/panel_control" className="boton-catalogo">admin</Link>
        </main>
        
        <Footer />
        </>
    );
    };

    export default Cliente;
